/* global Word, Office */

// ===== API Configuration =====
const PROVIDERS = {
  ollama: {
    baseUrl: 'http://localhost:11434',
    endpoint: '/api/generate',
    modelName: 'coney_/gpt-oss_claude-sonnet4.6',
  },
  lmstudio: {
    baseUrl: 'http://localhost:1234',
    endpoint: '/v1/chat/completions',
    modelName: 'local-model',
  }
};

const API_DEFAULTS = {
  maxTokens: 500,
  temperature: 0.7,
};

// Default provider (can be changed via localStorage if needed)
let currentProvider = 'ollama';

Office.onReady(() => {
  // Office.js is ready to be called
});

/**
 * Chèn văn bản máy tạo vào tài liệu Word
 * @param event {Office.AddinCommands.Event}
 */
function insertGeneratedText(event) {
  Word.run(async (context) => {
    try {
      const prompt = "Hãy tạo một đoạn văn thú vị về kỹ thuật AI.";
      
      const provider = PROVIDERS[currentProvider];
      let payload;

      if (currentProvider === 'ollama') {
        payload = {
          model: provider.modelName,
          prompt: prompt,
          max_tokens: API_DEFAULTS.maxTokens,
          temperature: API_DEFAULTS.temperature,
          stream: false
        };
      } else if (currentProvider === 'lmstudio') {
        payload = {
          model: provider.modelName,
          messages: [
            { role: "user", content: prompt }
          ],
          max_tokens: API_DEFAULTS.maxTokens,
          temperature: API_DEFAULTS.temperature
        };
      }

      // Sử dụng XMLHttpRequest thay cho fetch để tương thích với Word 2019 (IE11)
      const generatedText = await new Promise((resolve, reject) => {
        const xhr = new XMLHttpRequest();
        xhr.open('POST', `${provider.baseUrl}${provider.endpoint}`, true);
        xhr.setRequestHeader('Content-Type', 'application/json');
        
        xhr.onload = function() {
          if (xhr.status >= 200 && xhr.status < 300) {
            try {
              const data = JSON.parse(xhr.responseText);
              // Ollama format
              if (data.response) {
                resolve(data.response);
              }
              // LM Studio / OpenAI format
              else if (data.choices && data.choices.length > 0) {
                resolve(data.choices[0].message?.content || data.choices[0].text);
              } else {
                reject(new Error("Không thể parse phản hồi từ API"));
              }
            } catch (e) {
              reject(new Error("Lỗi parse JSON: " + e.message));
            }
          } else {
            reject(new Error("Lỗi HTTP: " + xhr.status));
          }
        };
        
        xhr.onerror = function() {
          reject(new Error("Lỗi mạng"));
        };
        
        xhr.send(JSON.stringify(payload));
      });

      if (generatedText) {
        // Chèn văn bản vào document
        context.document.body.insertParagraph(
          generatedText,
          Word.InsertLocation.end
        );
      }
      
      await context.sync();
    } catch (error) {
      console.error('Error:', error);
    } finally {
      event.completed();
    }
  });
}

/**
 * Cập nhật thanh trạng thái
 * @param event {Office.AddinCommands.Event}
 */
function getDocumentStats(event) {
  Word.run(async (context) => {
    const body = context.document.body;
    body.load("text");
    
    await context.sync();
    
    const wordCount = body.text.split(/\s+/).length;
    console.log(`Document has ${wordCount} words.`);
  });
  
  event.completed();
}

// Register the functions with Office
Office.actions.associate("insertGeneratedText", insertGeneratedText);
Office.actions.associate("getDocumentStats", getDocumentStats);
